/*
 * A192645  Monotonic ordering of set S generated by these rules: if x and y
 *          are in S and x^2 - y^2 > 0 then x^2 - y^2 is in S, and 1 and 2 are
 *          in S.
 * https://oeis.org/A192645
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   A192645 - monotonic ordering of set S defined by * "if x and y
 *            are in S and x^2 - y^2 > 0 then x^2 - y^2 is in S, *
 *            start={1,2}". The sequence is generated by a min‑heap of the *
 *            differences x^2 - y^2 for each fixed x and descending y
 * Range:     u8 n <= 12, u16 n <= 226, u32 n <= 2619, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* A node represents one stream (fixed x, decreasing y). */
typedef struct {
    seq_t diff;   /* current difference x^2 - y^2 */
    idx_t k;      /* index of the larger element x in S */
    idx_t j;      /* current index of the smaller element y */
} Node;

/* Min‑heap of Nodes */
typedef struct {
    Node *data;
    size_t size;
    size_t cap;
} Heap;

/* Global state: sequence array and the heap */
static seq_t *seq      = NULL;
static size_t  seq_cap = 0;
static idx_t   seq_len = 0;

static Heap heap = {NULL, 0, 0};

/* Extend the sequence array if needed. */
static void seq_push(seq_t v)
{
    if (seq_len == seq_cap) {
        size_t new_cap = seq_cap ? seq_cap * 2 : 4;
        seq_t *tmp = (seq_t*)realloc(seq, new_cap * sizeof(seq[0]));
        seq = tmp;
        seq_cap = new_cap;
    }
    seq[seq_len++] = v;
}

/* Push a node onto the min‑heap. */
static void heap_push(Heap *h, Node v)
{
    if (h->size == h->cap) {
        size_t new_cap = h->cap ? h->cap * 2 : 16;
        Node *tmp = (Node*)realloc(h->data, new_cap * sizeof(Node));
        h->data = tmp;
        h->cap = new_cap;
    }
    size_t i = h->size++;
    h->data[i] = v;
    /* sift‑up */
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (h->data[parent].diff <= h->data[i].diff)
            break;
        Node t = h->data[parent];
        h->data[parent] = h->data[i];
        h->data[i] = t;
        i = parent;
    }
}

/* Pop the smallest node from the heap. */
static Node heap_pop(Heap *h)
{
    Node res = h->data[0];
    h->size--;
    if (h->size > 0) {
        h->data[0] = h->data[h->size];
        size_t i = 0;
        while (1) {
            size_t left  = (i << 1) + 1;
            size_t right = left + 1;
            size_t smallest = i;
            if (left < h->size && h->data[left].diff < h->data[smallest].diff)
                smallest = left;
            if (right < h->size && h->data[right].diff < h->data[smallest].diff)
                smallest = right;
            if (smallest == i)
                break;
            Node t = h->data[i];
            h->data[i] = h->data[smallest];
            h->data[smallest] = t;
            i = smallest;
        }
    }
    return res;
}

/* Ensure the initial sequence 1,2 and the heap containing the first
 * difference 2^2 - 1^2 are set up.  The setup is performed only once. */
static void init_sequence_and_heap(void)
{
    if (seq_len != 0)       /* already initialised */
        return;

    /* Allocate initial storage for the sequence array. */
    seq_cap = 4;
    seq = (seq_t*)calloc(seq_cap, sizeof(seq[0]));
    seq[0] = (seq_t)1;
    seq[1] = (seq_t)2;
    seq_len = 2;

    /* Initialise the min‑heap. */
    heap.cap = 16;
    heap.data = (Node*)calloc(heap.cap, sizeof(Node));
    heap.size = 0;

    /* First candidate 2^2 - 1^2 = 3. */
    seq_t diff = (seq_t)4 - (seq_t)1;
    heap_push(&heap, (Node){diff, 1, 0});
}

/* Main sequence function.  n is 1‑based. */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;     /* undefined for n==0, but safe */

    init_sequence_and_heap();

    /* Generate terms until we have at least n of them. */
    while ((idx_t)seq_len < n) {
        Node node = heap_pop(&heap);
        seq_t val = node.diff;

        /* Skip duplicates. */
        if (seq_len > 0 && val == seq[seq_len - 1]) {
            /* Advance this stream. */
            if (node.j > 0) {
                idx_t next_j = node.j - 1;
                seq_t next_diff = seq[node.k] * seq[node.k] -
                                  seq[next_j] * seq[next_j];
                heap_push(&heap, (Node){next_diff, node.k, next_j});
            }
            continue;
        }

        /* Add new value to the sequence. */
        seq_push(val);

        /* Advance this stream (if possible). */
        if (node.j > 0) {
            idx_t next_j = node.j - 1;
            seq_t next_diff = seq[node.k] * seq[node.k] -
                              seq[next_j] * seq[next_j];
            heap_push(&heap, (Node){next_diff, node.k, next_j});
        }

        /* Start a new stream for the newly added element. */
        idx_t new_k = seq_len - 1;            /* index of new element */
        if (new_k > 0) {
            idx_t start_j = new_k - 1;
            seq_t start_diff = seq[new_k] * seq[new_k] -
                               seq[start_j] * seq[start_j];
            heap_push(&heap, (Node){start_diff, new_k, start_j});
        }
    }

    /* Return the requested term. */
    return seq[n - 1];
}
